package detector

import (
	"bytes"
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"runtime"
	"slices"
	"strings"
	"testing"

	"github.com/step-security/dev-machine-guard/internal/detector/configaudit"
	"github.com/step-security/dev-machine-guard/internal/model"
)

// The shared contract is generated by the real guarded scanner over the
// fixture tree. Host-specific paths and the IDs derived from them are normalized.
func TestMavenGoldenProducer(t *testing.T) {
	if runtime.GOOS == model.PlatformWindows {
		t.Skip("canonical Unix fixture; wire round-trip and scanner tests also run on Windows")
	}
	home := goTestHome(t)
	root := filepath.Join(home, "projects")
	mavenWriteFixture(t, home, root)
	scanner, _ := mavenTestScanner(t, home)
	inv, maven, gradle := scanner.Scan(context.Background(), goTestTarget(home), []string{root}, nil)
	mavenAssertRefs(t, inv)
	type sections struct {
		Inventory *model.MavenInventory    `json:"maven_inventory"`
		Maven     *model.MavenConfigAudit  `json:"maven_config_audit"`
		Gradle    *model.GradleConfigAudit `json:"gradle_config_audit"`
	}
	pair := sections{inv, maven, gradle}
	raw, err := json.Marshal(pair)
	if err != nil {
		t.Fatal(err)
	}
	raw = []byte(strings.ReplaceAll(string(raw), home, "/home/maven-fixture"))
	if err := json.Unmarshal(raw, &pair); err != nil {
		t.Fatal(err)
	}
	replacements := []string{}
	for _, s := range pair.Inventory.Sources {
		replacements = append(replacements, s.SourceID, configaudit.GoSourceID(goTestTarget(home).Username, s.Kind, s.Path))
	}
	for _, a := range []*model.MavenConfigAudit{pair.Maven, pair.Gradle} {
		for _, f := range a.Files {
			replacements = append(replacements, f.SourceID, configaudit.GoSourceID(goTestTarget(home).Username, configaudit.MavenConfigKind(f.Manager, f.Scope), f.Path))
		}
	}
	raw = []byte(strings.NewReplacer(replacements...).Replace(string(raw)))
	if err := json.Unmarshal(raw, &pair); err != nil {
		t.Fatal(err)
	}
	for i := range pair.Inventory.Sources {
		slices.Sort(pair.Inventory.Sources[i].DiscoveredSources)
	}
	for _, a := range []*model.MavenConfigAudit{pair.Maven, pair.Gradle} {
		slices.SortFunc(a.Findings, func(x, y model.CargoConfigFinding) int {
			return strings.Compare(x.Code+x.SourceID+x.Key, y.Code+y.SourceID+y.Key)
		})
		slices.SortFunc(a.Contexts, func(x, y model.RubyConfigContext) int {
			return strings.Compare(x.ProjectPath+"\x00"+strings.Join(x.ConfigSourceIDs, ","), y.ProjectPath+"\x00"+strings.Join(y.ConfigSourceIDs, ","))
		})
	}
	mavenAssertRefs(t, pair.Inventory)
	raw, err = json.MarshalIndent(pair, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	raw = append(raw, '\n')
	path := "../model/testdata/maven_inventory_v1_golden.json"
	if os.Getenv("UPDATE_MAVEN_GOLDEN") == "1" {
		if err := os.WriteFile(path, raw, 0o600); err != nil {
			t.Fatal(err)
		}
	}
	want, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(raw, want) {
		t.Fatal("producer differs from shared Maven golden; review the contract before regenerating")
	}
}
